.strategygap-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243524;
    background: linear-gradient(160deg, #f3f6ec 0%, #e7f0df 100%);
    border-radius: 18px;
}

.strategygap-container * {
    box-sizing: border-box;
}

.strategygap-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1d3a2a 0%, #2f6b43 55%, #4f9a5e 100%);
    color: #f4fbf0;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(29, 58, 42, 0.30);
}

.strategygap-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.strategygap-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #cdebc4;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.strategygap-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3f3da;
}

.strategygap-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2f5a3a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.strategygap-period-counter #currentDay,
.strategygap-period-counter #maxPeriods {
    font-weight: 800;
    color: #1d3a2a;
}

.strategygap-round-name {
    background: #d6ead0;
    color: #1d3a2a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.strategygap-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a16;
    background: #f6e6cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.strategygap-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.strategygap-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d8e6cf;
    box-shadow: 0 4px 14px rgba(29, 58, 42, 0.06);
    border-top: 4px solid #4f9a5e;
}

.strategygap-card-execution { border-top-color: #2f6b43; }
.strategygap-card-buyin { border-top-color: #2f7fb0; }
.strategygap-card-sustain { border-top-color: #6a9a2f; }
.strategygap-card-efficiency { border-top-color: #c98a16; }

.strategygap-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7d63;
}

.strategygap-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1d3a2a;
}

.strategygap-card-execution .strategygap-value { color: #2f6b43; }
.strategygap-card-buyin .strategygap-value { color: #2f7fb0; }
.strategygap-card-sustain .strategygap-value { color: #5a861f; }
.strategygap-card-efficiency .strategygap-value { color: #c98a16; }

.strategygap-sublabel {
    font-size: 0.76rem;
    color: #7d8f76;
    line-height: 1.35;
}

.strategygap-execution-fail .strategygap-value { color: #c0392b; }
.strategygap-execution-target .strategygap-value { color: #2f6b43; }

.strategygap-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1d3a2a;
    color: #eaf6e4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.strategygap-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.strategygap-budget-over #budgetDisplay {
    color: #ffb3a7;
}

.strategygap-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4f9a5e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(29, 58, 42, 0.05);
}

.strategygap-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.strategygap-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1d3a2a;
    margin-bottom: 6px;
}

.strategygap-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34492f;
}

.strategygap-briefing-text strong { color: #2f6b43; }
.strategygap-briefing-text em { color: #9a5a16; font-style: italic; }

.strategygap-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d8e6cf;
    box-shadow: 0 4px 14px rgba(29, 58, 42, 0.06);
}

.strategygap-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1d3a2a;
    border-bottom: 2px solid #e7f0df;
    padding-bottom: 8px;
}

.strategygap-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a4530;
    margin: 14px 0 6px;
}

.strategygap-container select,
.strategygap-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd5b2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbf3;
    color: #243524;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.strategygap-container select:focus,
.strategygap-container input[type="number"]:focus {
    outline: none;
    border-color: #4f9a5e;
    box-shadow: 0 0 0 3px rgba(79, 154, 94, 0.16);
}

.strategygap-container select option {
    background-color: #ffffff;
    color: #243524;
}

.strategygap-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4f9a5e;
}

.strategygap-range-readout,
.strategygap-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f6b43;
    margin-top: 4px;
}

.strategygap-range-readout span:last-child,
.strategygap-alloc-readout span:nth-child(2) {
    color: #5a861f;
    font-weight: 800;
}

.strategygap-hint {
    font-size: 0.8rem;
    color: #7d8f76;
    margin-top: 4px;
    line-height: 1.4;
}

.strategygap-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.strategygap-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f1f7ec;
    border: 1px solid #dcebd2;
    border-radius: 9px;
    padding: 8px 12px;
}

.strategygap-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a4530;
}

.strategygap-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.strategygap-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.strategygap-container .btn-primary {
    background: linear-gradient(135deg, #2f6b43 0%, #4f9a5e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 107, 67, 0.28);
}

.strategygap-container .btn-primary:hover {
    filter: brightness(1.06);
}

.strategygap-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd5b2;
    color: #6a7d63;
}

.strategygap-coach {
    background: #1d3a2a;
    color: #eaf6e4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(29, 58, 42, 0.22);
}

.strategygap-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #97cf9a;
    margin-bottom: 8px;
}

.strategygap-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.strategygap-coach-body strong { color: #ffe08a; }
.strategygap-coach-body em { color: #ffc9a0; font-style: italic; }

.strategygap-history,
.strategygap-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d8e6cf;
    box-shadow: 0 4px 14px rgba(29, 58, 42, 0.06);
}

.strategygap-history h3,
.strategygap-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1d3a2a;
}

.strategygap-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a4530;
}

.strategygap-container table#usfHistoryTable th {
    background: #eaf3e3;
    color: #1d3a2a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6c9;
}

.strategygap-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4e8;
}

.strategygap-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf4;
}

.strategygap-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .strategygap-container {
        padding: 14px;
    }
    .strategygap-header h1 {
        font-size: 1.7rem;
    }
    .strategygap-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .strategygap-value {
        font-size: 2rem;
    }
    .strategygap-clock {
        margin-left: 0;
    }
    .strategygap-period-counter {
        font-size: 0.88rem;
    }
    .strategygap-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .strategygap-alloc-row {
        flex-wrap: wrap;
    }
    .strategygap-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .strategygap-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

