(function() {
    'use strict';

    function fmtMoney(valueM, lang) {
        // valueM is a number in millions of EUR. Locale-aware:
        // EN: "€30.0M" (symbol before, dot decimal). ES: "30,0 M€" (symbol after, comma decimal).
        const oneDp = Math.round(valueM * 10) / 10;
        if (lang === `es`) {
            return oneDp.toFixed(1).replace(`.`, `,`) + ` M€`;
        }
        return `€` + oneDp.toFixed(1) + `M`;
    }

    class StrategyGapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Closing the Strategy Gap`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (€M and 0-100 KPIs).
            this.START_EXECUTION = 5;     // near-zero at the 6-month audit
            this.START_BUYIN = 25;        // 38% call it "greenwash slides"
            this.START_SUSTAIN = 0;       // 2027 milestones not yet moving
            this.TARGET_EXECUTION = 70;   // credible execution trajectory
            this.BUDGET_CAP = 30;         // EUR 30M, fixed

            // Concept truths.
            this.TRUE_CAUSE = `implementation`;   // Thomas: implementation gap, not formulation
            this.TRUE_BARRIER = `incentives`;     // agency theory: single highest-leverage move
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    execution: this.START_EXECUTION,
                    buyin: this.START_BUYIN,
                    sustain: this.START_SUSTAIN,
                    budgetUsed: 0,
                    efficiency: 0,
                    efficiencySet: false,
                    shelved: false,
                    optics: false,
                    executionHistory: [this.START_EXECUTION],
                    buyinHistory: [this.START_BUYIN],
                    sustainHistory: [this.START_SUSTAIN],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — not the textbook-correct play.
                state.decisions = {
                    cause: `ambition`,
                    barrier: `suppliers`,
                    focus: 50,
                    count: `moderate`,
                    foundations: 9,
                    flagship: 12,
                    reserve: 9,
                    dependency: `parallel`,
                    incentive: 20,
                    ownership: `committee`,
                    capability: `hire`,
                    engagement: `develop`,
                    checkpoint: `annual`,
                    milestone: `loan`,
                    board: `reassure`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cause = document.getElementById(`causeInput`);
                const barrier = document.getElementById(`barrierInput`);
                const focus = document.getElementById(`focusInput`);
                if (cause) decisions.cause = cause.value;
                if (barrier) decisions.barrier = barrier.value;
                if (focus) decisions.focus = parseInt(focus.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const count = document.getElementById(`countInput`);
                const dep = document.getElementById(`dependencyInput`);
                if (count) decisions.count = count.value;
                if (dep) decisions.dependency = dep.value;
                const fnd = document.getElementById(`foundationsInput`);
                const flg = document.getElementById(`flagshipInput`);
                const rsv = document.getElementById(`reserveInput`);
                if (fnd) decisions.foundations = parseFloat(fnd.value);
                if (flg) decisions.flagship = parseFloat(flg.value);
                if (rsv) decisions.reserve = parseFloat(rsv.value);
                const parts = [decisions.foundations, decisions.flagship, decisions.reserve];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.foundations + decisions.flagship + decisions.reserve) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const inc = document.getElementById(`incentiveInput`);
                const own = document.getElementById(`ownershipInput`);
                const cap = document.getElementById(`capabilityInput`);
                const eng = document.getElementById(`engagementInput`);
                if (inc) decisions.incentive = parseInt(inc.value, 10);
                if (own) decisions.ownership = own.value;
                if (cap) decisions.capability = cap.value;
                if (eng) decisions.engagement = eng.value;
                if (!Number.isFinite(decisions.incentive) || decisions.incentive < 0 || decisions.incentive > 100) {
                    warn(`warn_incentive_range`); return false;
                }
            } else if (round === 4) {
                const chk = document.getElementById(`checkpointInput`);
                const mil = document.getElementById(`milestoneInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (chk) decisions.checkpoint = chk.value;
                if (mil) decisions.milestone = mil.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let execDelta = 0, buyinDelta = 0, sustainDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: implementation gap, not formulation (Common Error 1 = re-strategising).
                if (d.cause === this.TRUE_CAUSE) {
                    execDelta += 8; buyinDelta += 6; coachKey = `coach_r1_cause_right`;
                } else if (d.cause === `formulation`) {
                    execDelta -= 6; buyinDelta -= 4; coachKey = `coach_r1_formulation`;
                } else if (d.cause === `ambition`) {
                    execDelta -= 4; buyinDelta -= 2; coachKey = `coach_r1_ambition`;
                } else {
                    execDelta -= 6; buyinDelta -= 6; coachKey = `coach_r1_people`;
                }

                // Highest-leverage barrier: misaligned incentives (agency theory). Overload is also
                // strong; comms (relaunch the deck) is the wrong instinct; suppliers is real but secondary.
                if (d.barrier === this.TRUE_BARRIER) {
                    execDelta += 6; buyinDelta += 8;
                    if (d.cause === this.TRUE_CAUSE) coachKey = `coach_r1_diag_sharp`;
                } else if (d.barrier === `overload`) {
                    execDelta += 5; buyinDelta += 3;
                } else if (d.barrier === `comms`) {
                    execDelta -= 6; buyinDelta -= 4; coachKey = `coach_r1_comms`;
                } else {
                    execDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_suppliers` : coachKey;
                }

                // Diagnostic sharpness: separating structural from sequencing problems.
                if (d.focus >= 60) { execDelta += 5; }
                else if (d.focus <= 25) { execDelta -= 5; coachKey = `coach_r1_lowfocus`; }

                summaryKey = (d.cause === this.TRUE_CAUSE && d.barrier === this.TRUE_BARRIER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sequence the portfolio under the EUR 30M cap (Common Errors 2 & 4).
                switch (d.count) {
                    case `focused`: execDelta += 10; buyinDelta += 4; sustainDelta += 4; coachKey = `coach_r2_focused`; break;
                    case `moderate`: execDelta += 3; buyinDelta += 2; break;
                    case `all`: execDelta -= 8; buyinDelta -= 2; sustainDelta -= 4; coachKey = `coach_r2_all`; break;
                }

                // Foundations-first allocation. Under-funding the unglamorous enablers reproduces the stall.
                if (d.foundations >= 12) { execDelta += 8; sustainDelta += 8; }
                else if (d.foundations >= 8) { execDelta += 4; sustainDelta += 3; }
                else { execDelta -= 4; sustainDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_nofoundations` : coachKey; }

                // Optics-first: over-funding the flagship refill range buys short-lived board applause.
                if (d.flagship >= 15) {
                    execDelta -= 6; sustainDelta -= 4; buyinDelta += 2; ds.optics = true;
                    coachKey = `coach_r2_flagshipheavy`;
                }

                // Dependency logic: build foundations before the visible launch.
                switch (d.dependency) {
                    case `foundationsfirst`: execDelta += 8; sustainDelta += 6; if (d.count === `focused` && d.foundations >= 12) coachKey = `coach_r2_sequenced`; break;
                    case `parallel`: execDelta += 2; break;
                    case `flagshipfirst`: execDelta -= 8; sustainDelta -= 6; buyinDelta += 3; ds.optics = true; coachKey = `coach_r2_flagshipfirst`; break;
                }

                // The full EUR 30M is committed when the portfolio is funded.
                spend = this.BUDGET_CAP;

                summaryKey = (d.count === `focused` && d.dependency === `foundationsfirst` && d.foundations >= 12 && d.flagship < 15) ? `sum_r2_good` : (d.count === `all` || d.dependency === `flagshipfirst` ? `sum_r2_optics` : `sum_r2_weak`);
            } else if (round === 3) {
                // Remove the barriers: incentives, ownership, capability, co-creation (Errors 3 & 5).
                // Incentive alignment — the single highest-leverage, most resisted move (agency theory).
                if (d.incentive >= 30 && d.incentive <= 55) {
                    execDelta += 10; buyinDelta += 8; coachKey = `coach_r3_incentive_right`;
                } else if (d.incentive < 15) {
                    execDelta -= 10; buyinDelta -= 6; coachKey = `coach_r3_incentive_untouched`;
                } else if (d.incentive >= 70) {
                    execDelta -= 2; buyinDelta -= 6; coachKey = `coach_r3_incentive_over`;
                } else {
                    execDelta += 3; buyinDelta += 2; coachKey = `coach_r3_incentive_partial`;
                }

                // Ownership: a named accountable owner beats a committee or "everyone's job".
                switch (d.ownership) {
                    case `named`: execDelta += 8; sustainDelta += 6; break;
                    case `committee`: sustainDelta += 1; break;
                    case `sponsor`: execDelta -= 6; sustainDelta -= 4; coachKey = `coach_r3_sponsor`; break;
                }

                // Capability build: partner now AND hire to own it beats hiring cold, retraining on the side, or deferring.
                switch (d.capability) {
                    case `partner`: execDelta += 8; sustainDelta += 6; break;
                    case `hire`: execDelta += 3; sustainDelta += 5; break;
                    case `retrain`: execDelta -= 2; sustainDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_retrain` : coachKey; break;
                    case `none`: execDelta -= 8; sustainDelta -= 6; coachKey = `coach_r3_nocapability`; break;
                }

                // Stakeholder engagement: co-creation (Thomas) vs compliance-mode (Error 5).
                switch (d.engagement) {
                    case `cocreate`: buyinDelta += 12; sustainDelta += 6; execDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r3_cocreate`; break;
                    case `develop`: buyinDelta += 5; sustainDelta += 3; execDelta += 2; break;
                    case `compliance`: buyinDelta -= 8; sustainDelta -= 4; execDelta -= 2; coachKey = `coach_r3_compliance`; break;
                }

                summaryKey = (d.incentive >= 30 && d.incentive <= 55 && d.ownership === `named` && d.engagement === `cocreate`) ? `sum_r3_good` : (d.incentive < 15 || d.engagement === `compliance` ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit & report (Common Error 6 + optics).
                switch (d.checkpoint) {
                    case `quarterly`: execDelta += 8; sustainDelta += 8; coachKey = `coach_r4_quarterly`; break;
                    case `annual`: sustainDelta += 1; break;
                    case `none`: execDelta -= 6; sustainDelta -= 6; coachKey = `coach_r4_nocheckpoint`; break;
                }

                switch (d.milestone) {
                    case `both`: sustainDelta += 12; buyinDelta += 4; break;
                    case `loan`: sustainDelta += 4; break;
                    case `defer`: sustainDelta -= 8; buyinDelta -= 4; coachKey = `coach_r4_defer`; break;
                }

                switch (d.board) {
                    case `honest`: buyinDelta += 10; sustainDelta += 4; if (d.checkpoint === `quarterly`) coachKey = `coach_r4_honest`; break;
                    case `reassure`: buyinDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_reassure` : coachKey; break;
                    case `optics`: buyinDelta -= 6; sustainDelta -= 4; ds.optics = true; coachKey = `coach_r4_optics`; break;
                }

                execDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.checkpoint === `quarterly` && d.milestone === `both` && d.board === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget is fully committed in round 2).
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // KPIs move on their deltas, bounded 0-100.
            ds.execution = Math.max(0, Math.min(100, ds.execution + execDelta));
            ds.buyin = Math.max(0, Math.min(100, ds.buyin + buyinDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));

            // Change-cost efficiency: execution delivered per EUR M committed (set once budget is spent).
            if (ds.budgetUsed > 0) {
                ds.efficiency = Math.round((ds.execution / ds.budgetUsed) * 10) / 10;
                ds.efficiencySet = true;
            }

            ds.executionHistory.push(Math.round(ds.execution));
            ds.buyinHistory.push(Math.round(ds.buyin));
            ds.sustainHistory.push(Math.round(ds.sustain));

            // Escalation: near-zero execution at the 18-month review shelves the strategy.
            if (round === this.ROUNDS.length && ds.execution < 15) ds.shelved = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                execution: Math.round(ds.execution),
                executionDelta: Math.round(execDelta),
                buyin: Math.round(ds.buyin),
                buyinDelta: Math.round(buyinDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                budgetUsed: ds.budgetUsed,
                efficiency: ds.efficiencySet ? ds.efficiency : null,
                optics: ds.optics,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            const lang = () => (window.mySimulation && window.mySimulation.language) || `en`;

            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`executionDisplay`, `domainState.execution`, (v) => {
                const card = document.querySelector(`.strategygap-card-execution`);
                if (card) {
                    card.classList.toggle(`strategygap-execution-target`, Number(v) >= this.TARGET_EXECUTION);
                    card.classList.toggle(`strategygap-execution-fail`, Number(v) < this.TARGET_EXECUTION);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`buyinDisplay`, `domainState.buyin`, (v) => Math.round(v));
            uiManager.bind(`sustainDisplay`, `domainState.sustain`, (v) => Math.round(v));
            uiManager.bind(`efficiencyDisplay`, `domainState.efficiency`, (v) => {
                const ds = window.mySimulation.state.domainState;
                if (!ds || !ds.efficiencySet) return `—`;
                return Number(v).toFixed(1);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.strategygap-budget-bar`);
                if (card) card.classList.toggle(`strategygap-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return fmtMoney(Number(v), lang()) + ` / ` + fmtMoney(this.BUDGET_CAP, lang());
            });

            // Focus slider readout.
            const focus = document.getElementById(`focusInput`);
            const focusReadout = document.getElementById(`focusReadout`);
            if (focus && focusReadout) {
                focusReadout.textContent = focus.value;
                focus.addEventListener(`input`, function() { focusReadout.textContent = focus.value; });
            }

            // Incentive slider readout.
            const inc = document.getElementById(`incentiveInput`);
            const incReadout = document.getElementById(`incentiveReadout`);
            if (inc && incReadout) {
                incReadout.textContent = inc.value;
                inc.addEventListener(`input`, function() { incReadout.textContent = inc.value; });
            }

            // Budget allocation live total (must equal EUR 30M).
            const allocIds = [`foundationsInput`, `flagshipInput`, `reserveInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.strategygap-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

