        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const execution = Math.round(ds.execution);
            const buyin = Math.round(ds.buyin);
            const sustain = Math.round(ds.sustain);

            const hitTarget = execution >= this.TARGET_EXECUTION;
            const realExecution = hitTarget && buyin >= 55 && sustain >= 50;
            const optics = ds.optics && hitTarget && (buyin < 45 || sustain < 40);
            const composite = Math.round(Math.min(100, execution) * 0.40 + buyin * 0.30 + sustain * 0.30);

            let performanceKey = `stalled_deck`;
            if (ds.shelved) performanceKey = `shelved`;
            else if (realExecution && composite >= 72) performanceKey = `gap_closed`;
            else if (realExecution) performanceKey = `credible_trajectory`;
            else if (optics) performanceKey = `optics`;
            else if (hitTarget) performanceKey = `numbers_thin`;
            else if (execution > this.START_EXECUTION + 20) performanceKey = `improving_short`;
            // Stable, language-independent tier handle for the grading/reporting layer (read from domainState).
            ds.performanceTier = performanceKey;
            // Localized label for the debrief overlay (fixes English label leaking on non-EN screens).
            const performance = window.mySimulation.t(`tier_` + performanceKey);

            const insights = [];
            if (realExecution) insights.push(window.mySimulation.t(`insight_closed`));
            else if (optics) insights.push(window.mySimulation.t(`insight_optics`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else if (ds.shelved) insights.push(window.mySimulation.t(`insight_shelved`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (sustain < 45) insights.push(window.mySimulation.t(`insight_milestone_risk`));
            if (buyin < 45) insights.push(window.mySimulation.t(`insight_lowbuyin`));
            if (realExecution && sustain >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                execution: execution,
                buyin: buyin,
                sustain: sustain,
                hitTarget: hitTarget,
                optics: optics,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.optics && state.currentPeriod >= 2) return window.mySimulation.t(`hint_optics`);
            if (ds.sustain < 20 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_milestone`);
            if (ds.buyin < 25) return window.mySimulation.t(`hint_buyin`);
            if (state.currentPeriod >= 3 && ds.execution < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.execution >= this.TARGET_EXECUTION && ds.buyin >= 55 && ds.sustain >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

