                    warn_focus_range:       `La nitidez diagnóstica debe ser un porcentaje entre 0 y 100.`,
                    warn_alloc_negative:    `Las asignaciones de presupuesto no pueden ser negativas.`,
                    warn_alloc_total:       `El presupuesto debe sumar exactamente 30 M€ — es fijo, sin ampliación. Reequilibra.`,
